from dataclasses import dataclass

from src.mythosmini.leaderboard.entries import LeaderboardEntry
from src.mythosmini.leaderboard.scoring import (
    build_wiki_normalization,
    efficiency_score,
    overall_score,
)


@dataclass(frozen=True)
class Placement:
    overall_rank: int
    efficiency_rank: int
    total_entries: int
    overall: float
    efficiency: float


def rank_of(value: float, others: list[float]) -> int:
    return 1 + sum(1 for other in others if other > value)


def compute_placement(
    candidate: LeaderboardEntry, leaderboard: list[LeaderboardEntry]
) -> Placement:
    combined = [*leaderboard, candidate]
    norm = build_wiki_normalization(combined)
    candidate_overall = overall_score(candidate, norm)
    candidate_efficiency = efficiency_score(candidate, norm)
    other_overalls = [overall_score(entry, norm) for entry in leaderboard]
    other_efficiencies = [efficiency_score(entry, norm) for entry in leaderboard]
    return Placement(
        overall_rank=rank_of(candidate_overall, other_overalls),
        efficiency_rank=rank_of(candidate_efficiency, other_efficiencies),
        total_entries=len(combined),
        overall=candidate_overall,
        efficiency=candidate_efficiency,
    )


def format_placement(label: str, placement: Placement) -> str:
    return (
        f"{label}: overall {placement.overall:.2f} "
        f"(rank {placement.overall_rank}/{placement.total_entries}), "
        f"efficiency {placement.efficiency:.2f} "
        f"(rank {placement.efficiency_rank}/{placement.total_entries})"
    )
